Lemma lapil_0RB1LD_1RC1RB_1LA1RC_1LA0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB1LD_1RC1RB_1LA1RC_1LA0LA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LD_1RC1RB_1LA1RC_1LA0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LD_1RC1RB_1LA1RC_1LA0LA p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_0RB1LD_1RC1RB_1LA1RC_1LA0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LD_1RC1RB_1LA1RC_1LA0LA j)].
    rewrite (gso_0RB1LD_1RC1RB_1LA1RC_1LA0LA p j E).
    exact (srun_sound tm true true chb_0RB1LD_1RC1RB_1LA1RC_1LA0LA B0_0RB1LD_1RC1RB_1LA1RC_1LA0LA BB1_0RB1LD_1RC1RB_1LA1RC_1LA0LA 4 9
             run_boot_0RB1LD_1RC1RB_1LA1RC_1LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 24), (cden [] [] j B1_0RB1LD_1RC1RB_1LA1RC_1LA0LA).
    split; [| exact (geo_0RB1LD_1RC1RB_1LA1RC_1LA0LA p j E)].
    rewrite (gxi_0RB1LD_1RC1RB_1LA1RC_1LA0LA j).
    exact (srun_sound tm true true che_0RB1LD_1RC1RB_1LA1RC_1LA0LA BE0_0RB1LD_1RC1RB_1LA1RC_1LA0LA B1_0RB1LD_1RC1RB_1LA1RC_1LA0LA 4 24
             run_exit_0RB1LD_1RC1RB_1LA1RC_1LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LD_1RC1RB_1LA1RC_1LA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LD_1RC1RB_1LA1RC_1LA0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LD_1RC1RB_1LA1RC_1LA0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LD_1RC1RB_1LA1RC_1LA0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 38.
  assert (H : match csteps tm 38 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 38 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LD_1RC1RB_1LA1RC_1LA0LA = Some t ->
