(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LD_1RC1RB_1LA1RC_1LA0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LD_1RC1RB_1LA1RC_1LA0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1LD_1RC1RB_1LA1RC_1LA0LA t p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_0RB1LD_1RC1RB_1LA1RC_1LA0LA). split;
      [| exact (gbo_0RB1LD_1RC1RB_1LA1RC_1LA0LA j)].
    rewrite (gso_0RB1LD_1RC1RB_1LA1RC_1LA0LA p j E).
    exact (srun_sound tm true true chb_0RB1LD_1RC1RB_1LA1RC_1LA0LA B0_0RB1LD_1RC1RB_1LA1RC_1LA0LA BB1_0RB1LD_1RC1RB_1LA1RC_1LA0LA 4 9
             run_boot_0RB1LD_1RC1RB_1LA1RC_1LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LD_1RC1RB_1LA1RC_1LA0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LD_1RC1RB_1LA1RC_1LA0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LD_1RC1RB_1LA1RC_1LA0LA : forall t, ~ In t pins_0RB1LD_1RC1RB_1LA1RC_1LA0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LD_1RC1RB_1LA1RC_1LA0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SCycL 2 0; SWin 2; SCycR 2; SWin 3; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SCycL 2 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SCycL 2 0; SWin 2; SCycR 2; SWin 3; SWinR 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LD_1RC1RB_1LA1RC_1LA0LA (StB, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SWin 2; SWinR 4; SCycL 2 0; SWin 4; SWinL 6; SCycR 2; SWin 3; SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SCycL 2 0; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA [] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LD_1RC1RB_1LA1RC_1LA0LA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SWin 2; SWinR 4; SCycL 2 0; SWin 4; SWinL 6; SCycR 2; SWin 3] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LD_1RC1RB_1LA1RC_1LA0LA [SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

