(** 0RB1LD_1RC1RC_1LA1RB_0RD0LA *)
(** 0RB1LD_1RC1RC_1LA1RB_0RD0LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LD_1RC1RC_1LA1RB_0RD0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S0 DL StA end.

(** Its mirror 0LB1RD_1LC1LC_1RA1LB_0LD0RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LD_1RC1RC_1LA1RB_0RD0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LD_1RC1RC_1LA1RB_0RD0LA : list Instr := [].
Definition tmw_0RB1LD_1RC1RC_1LA1RB_0RD0LA : TM := tm_wrap_trs tmm_0RB1LD_1RC1RC_1LA1RB_0RD0LA pins_0RB1LD_1RC1RC_1LA1RB_0RD0LA.
