Lemma gen_0RB1LD_1RC1RD_1LA1RC_1RB0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LD_1RC1RD_1LA1RC_1RB0LA) = lift (Cin (Pos.succ v)).
