  exists (4 * i + 6), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LD_1RC1RD_1LA1RC_1RB0LA).
  split; [lia|]. split; [| exact (gen_0RB1LD_1RC1RD_1LA1RC_1RB0LA v i q0 E)].
  rewrite (gsn_0RB1LD_1RC1RD_1LA1RC_1RB0LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LD_1RC1RD_1LA1RC_1RB0LA AI0_0RB1LD_1RC1RD_1LA1RC_1RB0LA AI1_0RB1LD_1RC1RD_1LA1RC_1RB0LA 4 6
           run_inner_0RB1LD_1RC1RD_1LA1RC_1RB0LA (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
