    apply (lap_of_run tm Cc true true cho_0RB1RA_1LA1LC_1LD0LD_0RA0LC B0_0RB1RA_1LA1LC_1LD0LD_0RA0LC B1_0RB1RA_1LA1LC_1LD0LD_0RA0LC 4 10 p j' [] []).
    + exact run_ovf_0RB1RA_1LA1LC_1LD0LD_0RA0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1RA_1LA1LC_1LD0LD_0RA0LC p j' E).
    + exact (geo_0RB1RA_1LA1LC_1LD0LD_0RA0LC p j' E).
