    exists (0 * 0 + 6), (cden (Dp q0 ++ [S0]) [] 0 Z1_0RB1RA_1LC0RA_1LD0LD_1LA0LC).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB1RA_1LC0RA_1LD0LD_1LA0LC Z0_0RB1RA_1LC0RA_1LD0LD_1LA0LC Z1_0RB1RA_1LC0RA_1LD0LD_1LA0LC 0 6
             run_z_0RB1RA_1LC0RA_1LD0LD_1LA0LC (Dp q0 ++ [S0]) [] 0
