    exact (srun_sound tm false true chp_0RB1RA_1LC0RA_1LD0LD_1LA0LC P0_0RB1RA_1LC0RA_1LD0LD_1LA0LC P1_0RB1RA_1LC0RA_1LD0LD_1LA0LC 4 10
