(** ** Bootstrap *)

Lemma boot_0RB1RA_1LC0RA_1LD0LD_1LA0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
