    apply (fireo_0RB1RA_1LC0RA_1LD0LD_1LA0LC [SWinR 4; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
