Lemma gsi_0RB1RA_1LC1LA_1LD1RB_0RC0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j A0_0RB1RA_1LC1LA_1LD1RB_0RC0LD.
