    rewrite (srun_sound tm false true chz_0RB1RA_1LC____1LD0LD_0RA0LC Z0_0RB1RA_1LC____1LD0LD_0RA0LC Z1_0RB1RA_1LC____1LD0LD_0RA0LC 0 4
