    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1RA_1LC____1LD0LD_0RA0LC
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
