(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StA (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StA (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chp_0RB1RB_0LC0RA_0LD1LA_1RA1LD : list lstep := [SWinR 4; SCycL 2 0; SWin 4; SCycR 2; SWin 10].

Lemma run_p_0RB1RB_0LC0RA_0LD1LA_1RA1LD : srun tm false true chp_0RB1RB_0LC0RA_0LD1LA_1RA1LD P0_0RB1RB_0LC0RA_0LD1LA_1RA1LD = Some (P1_0RB1RB_0LC0RA_0LD1LA_1RA1LD, 4, 18).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StA (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StD *)
Definition Cin_0RB1RB_0LC0RA_0LD1LA_1RA1LD (v : positive) : cconf := (StD, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1RB_0LC0RA_0LD1LA_1RA1LD.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chn_0RB1RB_0LC0RA_0LD1LA_1RA1LD : list lstep := [SWinR 4; SCycL 2 0; SWin 4; SCycR 2; SWin 4].

Lemma run_inner_0RB1RB_0LC0RA_0LD1LA_1RA1LD : srun tm false true chn_0RB1RB_0LC0RA_0LD1LA_1RA1LD AI0_0RB1RB_0LC0RA_0LD1LA_1RA1LD = Some (AI1_0RB1RB_0LC0RA_0LD1LA_1RA1LD, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chb_0RB1RB_0LC0RA_0LD1LA_1RA1LD : list lstep := [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 4].

Lemma run_boot_0RB1RB_0LC0RA_0LD1LA_1RA1LD : srun tm true true chb_0RB1RB_0LC0RA_0LD1LA_1RA1LD B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD = Some (BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD, 4, 11).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1RB_0LC0RA_0LD1LA_1RA1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1RB_0LC0RA_0LD1LA_1RA1LD : list lstep := [SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2; SRotL 1; SWin 7; SFoldL 1].

Lemma run_exit_0RB1RB_0LC0RA_0LD1LA_1RA1LD : srun tm true true che_0RB1RB_0LC0RA_0LD1LA_1RA1LD BE0_0RB1RB_0LC0RA_0LD1LA_1RA1LD = Some (B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD, 4, 19).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB1RB_0LC0RA_0LD1LA_1RA1LD /\
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB1RB_0LC0RA_0LD1LA_1RA1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1RB_0LC0RA_0LD1LA_1RA1LD, cden, Z0_0RB1RB_0LC0RA_0LD1LA_1RA1LD, Z1_0RB1RB_0LC0RA_0LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_0RB1RB_0LC0RA_0LD1LA_1RA1LD /\
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_0RB1RB_0LC0RA_0LD1LA_1RA1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1RB_0LC0RA_0LD1LA_1RA1LD, cden, P0_0RB1RB_0LC0RA_0LD1LA_1RA1LD, P1_0RB1RB_0LC0RA_0LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1RB_0LC0RA_0LD1LA_1RA1LD p q0 E) as (HA & HB).
    exists (0 * 0 + 14), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB1RB_0LC0RA_0LD1LA_1RA1LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB1RB_0LC0RA_0LD1LA_1RA1LD Z0_0RB1RB_0LC0RA_0LD1LA_1RA1LD Z1_0RB1RB_0LC0RA_0LD1LA_1RA1LD 0 14
             run_z_0RB1RB_0LC0RA_0LD1LA_1RA1LD (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 18), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j' P1_0RB1RB_0LC0RA_0LD1LA_1RA1LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_0RB1RB_0LC0RA_0LD1LA_1RA1LD P0_0RB1RB_0LC0RA_0LD1LA_1RA1LD P1_0RB1RB_0LC0RA_0LD1LA_1RA1LD 4 18
             run_p_0RB1RB_0LC0RA_0LD1LA_1RA1LD (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB1RB_0LC0RA_0LD1LA_1RA1LD, cden, B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD
             = (StA, (rep [S1;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1RB_0LC0RA_0LD1LA_1RA1LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB1RB_0LC0RA_0LD1LA_1RA1LD. reflexivity.
Qed.

Lemma gsn_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB1RB_0LC0RA_0LD1LA_1RA1LD.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB1RB_0LC0RA_0LD1LA_1RA1LD, cden, AI0_0RB1RB_0LC0RA_0LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB1RB_0LC0RA_0LD1LA_1RA1LD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB1RB_0LC0RA_0LD1LA_1RA1LD, cden, AI1_0RB1RB_0LC0RA_0LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0;S0]) with ((([]) ++ [S0]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1RB_0LC0RA_0LD1LA_1RA1LD).
  split; [lia|]. split; [| exact (gen_0RB1RB_0LC0RA_0LD1LA_1RA1LD v i q0 E)].
  rewrite (gsn_0RB1RB_0LC0RA_0LD1LA_1RA1LD v i q0 E).
  exact (srun_sound tm false true chn_0RB1RB_0LC0RA_0LD1LA_1RA1LD AI0_0RB1RB_0LC0RA_0LD1LA_1RA1LD AI1_0RB1RB_0LC0RA_0LD1LA_1RA1LD 4 12
           run_inner_0RB1RB_0LC0RA_0LD1LA_1RA1LD (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/2
    trailing blanks. *)
Lemma gbo_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall j, lift (cden [] [] j BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD = (StD, (rep [S1;S0] j ++ [S1;S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1RB_0LC0RA_0LD1LA_1RA1LD. rewrite epow2_0RB1RB_0LC0RA_0LD1LA_1RA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1RB_0LC0RA_0LD1LA_1RA1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1RB_0LC0RA_0LD1LA_1RA1LD.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1RB_0LC0RA_0LD1LA_1RA1LD, cden, BE0_0RB1RB_0LC0RA_0LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB1RB_0LC0RA_0LD1LA_1RA1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1RB_0LC0RA_0LD1LA_1RA1LD p (pow2 j)).
  - exists (4 * j + 11), (cden [] [] j BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD).
    split; [lia|]. split; [| exact (gbo_0RB1RB_0LC0RA_0LD1LA_1RA1LD j)].
    rewrite (gso_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j E).
    exact (srun_sound tm true true chb_0RB1RB_0LC0RA_0LD1LA_1RA1LD B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD BB1_0RB1RB_0LC0RA_0LD1LA_1RA1LD 4 11
             run_boot_0RB1RB_0LC0RA_0LD1LA_1RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 19), (cden [] [] j B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD).
    split; [| exact (geo_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j E)].
    rewrite (gxi_0RB1RB_0LC0RA_0LD1LA_1RA1LD j).
    exact (srun_sound tm true true che_0RB1RB_0LC0RA_0LD1LA_1RA1LD BE0_0RB1RB_0LC0RA_0LD1LA_1RA1LD B1_0RB1RB_0LC0RA_0LD1LA_1RA1LD 4 19
             run_exit_0RB1RB_0LC0RA_0LD1LA_1RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1RB_0LC0RA_0LD1LA_1RA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 18.
  assert (H : match csteps tm 18 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 18 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RB_0LC0RA_0LD1LA_1RA1LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1RB_0LC0RA_0LD1LA_1RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1RB_0LC0RA_0LD1LA_1RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1RB_0LC0RA_0LD1LA_1RA1LD t p (pow2 j)).
