    intros p1 j1 E1.
    exact (firex_0RB1RB_0LC0RA_0LD1LA_1RA1LD [SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1RB_0LC0RA_0LD1LA_1RA1LD [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
