Lemma run_int_0RB1RB_0LC0RA_0LD1RC_1RA1LD : srun tm false true chi_0RB1RB_0LC0RA_0LD1RC_1RA1LD A0_0RB1RB_0LC0RA_0LD1RC_1RA1LD = Some (A1_0RB1RB_0LC0RA_0LD1RC_1RA1LD, 4, 6).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1RB_0LC0RA_0LD1RC_1RA1LD : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1RB_0LC0RA_0LD1RC_1RA1LD : sconf := mkC StB (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StD *)
Definition Cin_0RB1RB_0LC0RA_0LD1RC_1RA1LD (v : positive) : cconf := (StD, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1RB_0LC0RA_0LD1RC_1RA1LD.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1RB_0LC0RA_0LD1RC_1RA1LD : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1RB_0LC0RA_0LD1RC_1RA1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1RB_0LC0RA_0LD1RC_1RA1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chn_0RB1RB_0LC0RA_0LD1RC_1RA1LD : list lstep := [SWinR 4; SCycL 2 0; SWin 4; SCycR 2; SWin 4].

Lemma run_inner_0RB1RB_0LC0RA_0LD1RC_1RA1LD : srun tm false true chn_0RB1RB_0LC0RA_0LD1RC_1RA1LD AI0_0RB1RB_0LC0RA_0LD1RC_1RA1LD = Some (AI1_0RB1RB_0LC0RA_0LD1RC_1RA1LD, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1RB_0LC0RA_0LD1RC_1RA1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chb_0RB1RB_0LC0RA_0LD1RC_1RA1LD : list lstep := [SRotL 1; SWin 3; SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 3].

Lemma run_boot_0RB1RB_0LC0RA_0LD1RC_1RA1LD : srun tm true true chb_0RB1RB_0LC0RA_0LD1RC_1RA1LD B0_0RB1RB_0LC0RA_0LD1RC_1RA1LD = Some (BB1_0RB1RB_0LC0RA_0LD1RC_1RA1LD, 4, 11).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1RB_0LC0RA_0LD1RC_1RA1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1RB_0LC0RA_0LD1RC_1RA1LD : list lstep := [SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1RB_0LC0RA_0LD1RC_1RA1LD : srun tm true true che_0RB1RB_0LC0RA_0LD1RC_1RA1LD BE0_0RB1RB_0LC0RA_0LD1RC_1RA1LD = Some (B1_0RB1RB_0LC0RA_0LD1RC_1RA1LD, 4, 11).
