  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1RB_0LC0RC_0LD1RA_1RC1LD : list Instr := [].
Definition tmw_0RB1RB_0LC0RC_0LD1RA_1RC1LD : TM := tm_wrap_trs tm_0RB1RB_0LC0RC_0LD1RA_1RC1LD pins_0RB1RB_0LC0RC_0LD1RA_1RC1LD.
Local Notation tm := tmw_0RB1RB_0LC0RC_0LD1RA_1RC1LD.

Definition Cc_0RB1RB_0LC0RC_0LD1RA_1RC1LD (p : positive) : cconf := (StC, (Ap_Alph_011_111_1 p ++ [S0], S0, [])).
