(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1RB_0LC0RC_0LD1RA_1RC1LD : sconf := mkC StA (mkS [] [S1;S0;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB1RB_0LC0RC_0LD1RA_1RC1LD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_0RB1RB_0LC0RC_0LD1RA_1RC1LD : srun tm true true chb_0RB1RB_0LC0RC_0LD1RA_1RC1LD B0_0RB1RB_0LC0RC_0LD1RA_1RC1LD = Some (BB1_0RB1RB_0LC0RC_0LD1RA_1RC1LD, 6, 4).
