  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1RB_0LC0RC_0LD1RA_1RC1LD, cden, AI0_0RB1RB_0LC0RC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1RB_0LC0RC_0LD1RA_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1RB_0LC0RC_0LD1RA_1RC1LD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1RB_0LC0RC_0LD1RA_1RC1LD, cden, AI1_0RB1RB_0LC0RC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1RB_0LC0RC_0LD1RA_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 6), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1RB_0LC0RC_0LD1RA_1RC1LD).
  split; [lia|]. split; [| exact (gen_0RB1RB_0LC0RC_0LD1RA_1RC1LD v i q0 E)].
  rewrite (gsn_0RB1RB_0LC0RC_0LD1RA_1RC1LD v i q0 E).
  exact (srun_sound tm false true chn_0RB1RB_0LC0RC_0LD1RA_1RC1LD AI0_0RB1RB_0LC0RC_0LD1RA_1RC1LD AI1_0RB1RB_0LC0RC_0LD1RA_1RC1LD 6 6
           run_inner_0RB1RB_0LC0RC_0LD1RA_1RC1LD (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1RB_0LC0RC_0LD1RA_1RC1LD : forall j, lift (cden [] [] j BB1_0RB1RB_0LC0RC_0LD1RA_1RC1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1RB_0LC0RC_0LD1RA_1RC1LD = (StA, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB1RB_0LC0RC_0LD1RA_1RC1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1RB_0LC0RC_0LD1RA_1RC1LD. rewrite epow2_0RB1RB_0LC0RC_0LD1RA_1RC1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1RB_0LC0RC_0LD1RA_1RC1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1RB_0LC0RC_0LD1RA_1RC1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_0RB1RB_0LC0RC_0LD1RA_1RC1LD.
Proof.
  intro j.
  destruct (Alph_101_111_1.cview_none_Alph_101_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1RB_0LC0RC_0LD1RA_1RC1LD, cden, BM0_0RB1RB_0LC0RC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

