Lemma run_p_0RB1RB_0LC0RD_1RD1LC_0LA1RA : srun tm false true chp_0RB1RB_0LC0RD_1RD1LC_0LA1RA P0_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Some (P1_0RB1RB_0LC0RD_1RD1LC_0LA1RA, 6, 10).
