Definition B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA : sconf := mkC StB (mkS [] [S0;S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_110_111_1 at StB *)
Definition Cin_0RB1RB_0LC0RD_1RD1LC_0LA1RA (v : positive) : cconf := (StB, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [])).
Local Notation Cin := Cin_0RB1RB_0LC0RD_1RD1LC_0LA1RA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1RB_0LC0RD_1RD1LC_0LA1RA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1RB_0LC0RD_1RD1LC_0LA1RA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB1RB_0LC0RD_1RD1LC_0LA1RA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_0RB1RB_0LC0RD_1RD1LC_0LA1RA : srun tm false true chn_0RB1RB_0LC0RD_1RD1LC_0LA1RA AI0_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Some (AI1_0RB1RB_0LC0RD_1RD1LC_0LA1RA, 6, 6).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB1RB_0LC0RD_1RD1LC_0LA1RA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SWinR 5; SUnrotL 2].

Lemma run_boot_0RB1RB_0LC0RD_1RD1LC_0LA1RA : srun tm true true chb_0RB1RB_0LC0RD_1RD1LC_0LA1RA B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Some (BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA, 6, 9).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1RB_0LC0RD_1RD1LC_0LA1RA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 4; SCycR 3; SWin 3; SRotL 2; SFoldL 1].

Lemma run_exit_0RB1RB_0LC0RD_1RD1LC_0LA1RA : srun tm true true che_0RB1RB_0LC0RD_1RD1LC_0LA1RA BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Some (B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1RB_0LC0RD_1RD1LC_0LA1RA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1RB_0LC0RD_1RD1LC_0LA1RA, cden, Z0_0RB1RB_0LC0RD_1RD1LC_0LA1RA, Z1_0RB1RB_0LC0RD_1RD1LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1RB_0LC0RD_1RD1LC_0LA1RA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1RB_0LC0RD_1RD1LC_0LA1RA, cden, P0_0RB1RB_0LC0RD_1RD1LC_0LA1RA, P1_0RB1RB_0LC0RD_1RD1LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1RB_0LC0RD_1RD1LC_0LA1RA p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1RB_0LC0RD_1RD1LC_0LA1RA Z0_0RB1RB_0LC0RD_1RD1LC_0LA1RA Z1_0RB1RB_0LC0RD_1RD1LC_0LA1RA 0 4
               run_z_0RB1RB_0LC0RD_1RD1LC_0LA1RA (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j' q0 E) as (HA & HB).
    exists (6 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1RB_0LC0RD_1RD1LC_0LA1RA P0_0RB1RB_0LC0RD_1RD1LC_0LA1RA P1_0RB1RB_0LC0RD_1RD1LC_0LA1RA 6 10
               run_p_0RB1RB_0LC0RD_1RD1LC_0LA1RA (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1RB_0LC0RD_1RD1LC_0LA1RA, cden, B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA
             = (StB, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1RB_0LC0RD_1RD1LC_0LA1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1RB_0LC0RD_1RD1LC_0LA1RA. reflexivity.
Qed.

Lemma gsn_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI0_0RB1RB_0LC0RD_1RD1LC_0LA1RA.
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1RB_0LC0RD_1RD1LC_0LA1RA, cden, AI0_0RB1RB_0LC0RD_1RD1LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1RB_0LC0RD_1RD1LC_0LA1RA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1RB_0LC0RD_1RD1LC_0LA1RA, cden, AI1_0RB1RB_0LC0RD_1RD1LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 6), (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1RB_0LC0RD_1RD1LC_0LA1RA).
  split; [lia|]. split; [| exact (gen_0RB1RB_0LC0RD_1RD1LC_0LA1RA v i q0 E)].
  rewrite (gsn_0RB1RB_0LC0RD_1RD1LC_0LA1RA v i q0 E).
  exact (srun_sound tm false true chn_0RB1RB_0LC0RD_1RD1LC_0LA1RA AI0_0RB1RB_0LC0RD_1RD1LC_0LA1RA AI1_0RB1RB_0LC0RD_1RD1LC_0LA1RA 6 6
           run_inner_0RB1RB_0LC0RD_1RD1LC_0LA1RA (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall j, lift (cden [] [] j BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold cden, BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin_0RB1RB_0LC0RD_1RD1LC_0LA1RA. rewrite epow2_0RB1RB_0LC0RD_1RD1LC_0LA1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1RB_0LC0RD_1RD1LC_0LA1RA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1RB_0LC0RD_1RD1LC_0LA1RA, cden, BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1RB_0LC0RD_1RD1LC_0LA1RA p (pow2 j)).
  - exists (6 * j + 9), (cden [] [] j BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA).
    split; [lia|]. split; [| exact (gbo_0RB1RB_0LC0RD_1RD1LC_0LA1RA j)].
    rewrite (gso_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j E).
    exact (srun_sound tm true true chb_0RB1RB_0LC0RD_1RD1LC_0LA1RA B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA 6 9
             run_boot_0RB1RB_0LC0RD_1RD1LC_0LA1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 10), (cden [] [] j B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA).
    split; [| exact (geo_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j E)].
    rewrite (gxi_0RB1RB_0LC0RD_1RD1LC_0LA1RA j).
    exact (srun_sound tm true true che_0RB1RB_0LC0RD_1RD1LC_0LA1RA BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA B1_0RB1RB_0LC0RD_1RD1LC_0LA1RA 6 10
             run_exit_0RB1RB_0LC0RD_1RD1LC_0LA1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1RB_0LC0RD_1RD1LC_0LA1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1RB_0LC0RD_1RD1LC_0LA1RA t p (pow2 j)).
  - exists (6 * j + 9), (cden [] [] j BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA). split;
      [| exact (gbo_0RB1RB_0LC0RD_1RD1LC_0LA1RA j)].
    rewrite (gso_0RB1RB_0LC0RD_1RD1LC_0LA1RA p j E).
    exact (srun_sound tm true true chb_0RB1RB_0LC0RD_1RD1LC_0LA1RA B0_0RB1RB_0LC0RD_1RD1LC_0LA1RA BB1_0RB1RB_0LC0RD_1RD1LC_0LA1RA 6 9
             run_boot_0RB1RB_0LC0RD_1RD1LC_0LA1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1RB_0LC0RD_1RD1LC_0LA1RA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1RB_0LC0RD_1RD1LC_0LA1RA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1RB_0LC0RD_1RD1LC_0LA1RA : forall t, ~ In t pins_0RB1RB_0LC0RD_1RD1LC_0LA1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
