Definition mk_0RB1RB_0LC1RA_1LD0RB_1RB1LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1RB_0LC1RA_1LD0RB_1RB1LC.

(** 0RB1RB_0LC1RA_1LD0RB_1RB1LC *)
Definition tm_0RB1RB_0LC1RA_1LD0RB_1RB1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1RB_0LC1RA_1LD0RB_1RB1LC : list Instr := [].
Definition tmw_0RB1RB_0LC1RA_1LD0RB_1RB1LC : TM := tm_wrap_trs tm_0RB1RB_0LC1RA_1LD0RB_1RB1LC pins_0RB1RB_0LC1RA_1LD0RB_1RB1LC.
Local Notation tm := tmw_0RB1RB_0LC1RA_1LD0RB_1RB1LC.

Definition Cc_0RB1RB_0LC1RA_1LD0RB_1RB1LC (p : positive) : cconf := (StC, (Jp p ++ [S1;S0], S0, [])).
Local Notation Cc := Cc_0RB1RB_0LC1RA_1LD0RB_1RB1LC.

(** ** The certificate *)

Definition A0_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chi_0RB1RB_0LC1RA_1LD0RB_1RB1LC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_int_0RB1RB_0LC1RA_1LD0RB_1RB1LC : srun tm false true chi_0RB1RB_0LC1RA_1LD0RB_1RB1LC A0_0RB1RB_0LC1RA_1LD0RB_1RB1LC = Some (A1_0RB1RB_0LC1RA_1LD0RB_1RB1LC, 4, 8).
