Definition B0_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StC *)
Definition Cin_0RB1RB_0LC1RA_1LD0RB_1RB1LC (v : positive) : cconf := (StC, (Jp v ++ [], S0, [])).
