(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chn_0RB1RB_0LC1RA_1LD0RB_1RB1LC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_inner_0RB1RB_0LC1RA_1LD0RB_1RB1LC : srun tm false true chn_0RB1RB_0LC1RA_1LD0RB_1RB1LC AI0_0RB1RB_0LC1RA_1LD0RB_1RB1LC = Some (AI1_0RB1RB_0LC1RA_1LD0RB_1RB1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chb_0RB1RB_0LC1RA_1LD0RB_1RB1LC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_boot_0RB1RB_0LC1RA_1LD0RB_1RB1LC : srun tm true true chb_0RB1RB_0LC1RA_1LD0RB_1RB1LC B0_0RB1RB_0LC1RA_1LD0RB_1RB1LC = Some (BB1_0RB1RB_0LC1RA_1LD0RB_1RB1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1RB_0LC1RA_1LD0RB_1RB1LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1RB_0LC1RA_1LD0RB_1RB1LC : list lstep := [SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWinR 3; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1RB_0LC1RA_1LD0RB_1RB1LC : srun tm true true che_0RB1RB_0LC1RA_1LD0RB_1RB1LC BE0_0RB1RB_0LC1RA_1LD0RB_1RB1LC = Some (B1_0RB1RB_0LC1RA_1LD0RB_1RB1LC, 4, 9).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_0RB1RB_0LC1RA_1LD0RB_1RB1LC.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_0RB1RB_0LC1RA_1LD0RB_1RB1LC, cden, A0_0RB1RB_0LC1RA_1LD0RB_1RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S1;S0]) [] j A1_0RB1RB_0LC1RA_1LD0RB_1RB1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_0RB1RB_0LC1RA_1LD0RB_1RB1LC, cden, A1_0RB1RB_0LC1RA_1LD0RB_1RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Jp q0 ++ [S1;S0]) [] j A1_0RB1RB_0LC1RA_1LD0RB_1RB1LC).
  split; [lia|]. split; [| exact (gei_0RB1RB_0LC1RA_1LD0RB_1RB1LC p j q0 E)].
  rewrite (gsi_0RB1RB_0LC1RA_1LD0RB_1RB1LC p j q0 E).
  exact (srun_sound tm false true chi_0RB1RB_0LC1RA_1LD0RB_1RB1LC A0_0RB1RB_0LC1RA_1LD0RB_1RB1LC A1_0RB1RB_0LC1RA_1LD0RB_1RB1LC 4 8
           run_int_0RB1RB_0LC1RA_1LD0RB_1RB1LC (Jp q0 ++ [S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1RB_0LC1RA_1LD0RB_1RB1LC.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_0RB1RB_0LC1RA_1LD0RB_1RB1LC, cden, B0_0RB1RB_0LC1RA_1LD0RB_1RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RB_0LC1RA_1LD0RB_1RB1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1RB_0LC1RA_1LD0RB_1RB1LC
             = (StC, (rep [S1;S1] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_0RB1RB_0LC1RA_1LD0RB_1RB1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1RB_0LC1RA_1LD0RB_1RB1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB1RB_0LC1RA_1LD0RB_1RB1LC. reflexivity.
Qed.

Lemma gsn_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall v i q0, cview v = (i, Some q0) ->
