Lemma gen_0RB1RB_0LC1RA_1LD0RB_1RB1LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ []) [] i AI1_0RB1RB_0LC1RA_1LD0RB_1RB1LC) = lift (Cin (Pos.succ v)).
