  apply (fire_via_fill tm Cc Cin lapin_0RB1RB_0LC1RA_1LD0RB_1RB1LC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1RB_0LC1RA_1LD0RB_1RB1LC). split;
      [| exact (gbo_0RB1RB_0LC1RA_1LD0RB_1RB1LC j)].
    rewrite (gso_0RB1RB_0LC1RA_1LD0RB_1RB1LC p j E).
    exact (srun_sound tm true true chb_0RB1RB_0LC1RA_1LD0RB_1RB1LC B0_0RB1RB_0LC1RA_1LD0RB_1RB1LC BB1_0RB1RB_0LC1RA_1LD0RB_1RB1LC 4 8
