  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1RB_0LC1RA_1LD0RB_1RB1LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1RB_0LC1RA_1LD0RB_1RB1LC j)].
Qed.

