    trailing blanks. *)
Lemma gbo_0RB1RB_0LC1RC_0LD0RA_1RA1LD : forall j, lift (cden [] [] j BB1_0RB1RB_0LC1RC_0LD0RA_1RA1LD) = lift (Cin (pow2 j)).
