  intro j.
  assert (HD : cden [] [] j BB1_0RB1RB_0LC1RC_0LD0RA_1RA1LD = (StB, (rep [S1;S0;S1] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_0RB1RB_0LC1RC_0LD0RA_1RA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1RB_0LC1RC_0LD0RA_1RA1LD. rewrite epow2_0RB1RB_0LC1RC_0LD0RA_1RA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1RB_0LC1RC_0LD0RA_1RA1LD. rewrite ?lift_app_blank. reflexivity.
